%%\ Lab 6: Mini Project – Integrated 2D DSP Image Processing Pipeline
% Problem: Structural Contour Extraction & Denoising under Low-Contrast Conditions
close all; clear; clc;

if ~exist('screenshots', 'dir')
    mkdir('screenshots');
end

%%\ 1) Load your own image (fallback to built-in sample if 'your_image.jpg' is absent)
if exist('your_image.jpg', 'file')
    img_name = 'your_image.jpg';
    I0 = imread(img_name);
elseif exist('peppers.png', 'file')
    img_name = 'peppers.png';
    I0 = imread(img_name);
else
    img_name = 'cameraman.tif';
    I0 = imread(img_name);
end

if size(I0, 3) == 3
    I = im2double(rgb2gray(I0));
else
    I = im2double(I0);
end

%%\ 2) Pre-process: Non-linear spatial noise removal
I_filt = medfilt2(I, [3 3]);

%%\ 3) Enhance contrast: Linear dynamic range stretching
I_enh = imadjust(I_filt, [0.2 0.8], [0 1]);

%%\ 4) Extract features: Multi-stage Canny edge detection
edges_raw = edge(I, 'Canny', [0.1 0.25]);     % Baseline edges before pipeline
edges     = edge(I_enh, 'Canny', [0.1 0.25]); % Edges after denoise + enhancement

%%\ 5) Frequency-domain low-pass mask (2D FFT)
F = fftshift(fft2(I_enh));
[M, N] = size(F);
[u, v] = meshgrid((-floor(N/2)):(ceil(N/2)-1), (-floor(M/2)):(ceil(M/2)-1));
D = sqrt(u.^2 + v.^2);

D0 = 60;
H = double(D < D0);
I_lp = real(ifft2(ifftshift(F .* H)));

% Quantitative summary metrics
energy_pct = sum(abs(F(:) .* H(:)).^2) / sum(abs(F(:)).^2) * 100;
fprintf('Image: %s (%d x %d)\n', img_name, M, N); %[output:1630706f]
fprintf('Canny Edge Pixels -> Raw: %d | After Pipeline: %d\n', nnz(edges_raw), nnz(edges)); %[output:09c4132b]
fprintf('Low-Pass Spectral Energy Retained (D0 = %d): %.2f%%\n', D0, energy_pct); %[output:98246f39]

%%\ 6) Visualization & Screenshot Export
% Figure 1: Full 6-panel pipeline progression
f1 = figure('Name', 'Lab 6 Pipeline Overview'); %[output:39048c52]
tiledlayout(2, 3, 'TileSpacing', 'compact', 'Padding', 'compact'); %[output:39048c52]

nexttile; imshow(I);                          title('1. Original Grayscale'); %[output:39048c52]
nexttile; imshow(I_filt);                     title('2. Median Denoised (3x3)'); %[output:39048c52]
nexttile; imshow(I_enh);                      title('3. Contrast Enhanced'); %[output:39048c52]
nexttile; imshow(edges);                      title(sprintf('4. Canny Edges (%d px)', nnz(edges))); %[output:39048c52]
nexttile; imshow(I_lp, []);                   title(sprintf('5. Ideal LP (D0 = %d)', D0)); %[output:39048c52]
nexttile; imshow(log(1 + abs(F .* H)), []);   title('6. Masked FFT Spectrum'); %[output:39048c52]

saveas(f1, fullfile('screenshots', '01_pipeline_overview.png')); %[output:39048c52]

% Figure 2: Before vs. After pre-processing on Canny edge detection
f2 = figure('Name', 'Edge Extraction Comparison'); %[output:6316bf4f]
tiledlayout(1, 2, 'TileSpacing', 'compact', 'Padding', 'compact'); %[output:6316bf4f]

nexttile; imshow(edges_raw); title(sprintf('Raw Canny Edges (%d px)', nnz(edges_raw))); %[output:6316bf4f]
nexttile; imshow(edges);     title(sprintf('Pipeline Canny Edges (%d px)', nnz(edges))); %[output:6316bf4f]

saveas(f2, fullfile('screenshots', '02_edge_comparison.png')); %[output:6316bf4f]

%%\ 7) Report
% -------------------------------------------------------------------------
% 1. Processing Pipeline Description
%    Problem: Extracting clean structural object boundaries from an image
%    affected by sensor grain and compressed mid-tone contrast.
%    Workflow:
%      - Stage 1: Convert RGB input to normalized 2D luminance I[m,n] in [0,1].
%      - Stage 2: Suppress impulse noise via a 3x3 median filter (I_filt).
%      - Stage 3: Stretch mid-tone intensities [0.2, 0.8] -> [0, 1] (I_enh).
%      - Stage 4: Extract 1-pixel contours with Canny edge detection (edges).
%      - Stage 5: Apply an ideal circular low-pass mask (D0 = 60) in the 2D
%        FFT domain (I_lp) to isolate coarse low-frequency structure.
%
% 2. Relation of Each Stage to 2D DSP Operations
%    - medfilt2: Non-linear rank-order spatial filter. Unlike linear FIR
%      averaging (which blurs step transitions), sorting 9 pixels in a 3x3
%      window and picking the median rejects outlier spikes while keeping
%      edges sharp.
%    - imadjust: Memoryless piecewise-linear pointwise mapping s = T(r) with
%      gain 1/0.6 (~1.67x) across [0.2, 0.8], amplifying local spatial
%      gradients |grad I| before edge detection.
%    - Canny edge: Linear derivative-of-Gaussian FIR gradient filtering
%      combined with non-maximum suppression (1-pixel thinning) and dual-
%      threshold hysteresis ([0.1, 0.25]) to connect continuous contours.
%    - fft2 / H / ifft2: Applies the 2D Convolution Theorem via pointwise
%      multiplication in the centered frequency domain, removing radial
%      frequencies D >= 60 to separate illumination from high-frequency edges.
%
% 3. Limitations & Potential Improvements
%    - Gibbs Ringing (Stage 5): The hard binary cutoff (D < 60) creates an
%      oscillating radial jinc impulse response in space, causing faint
%      ripples near sharp edges. A smooth Gaussian LP filter eliminates this.
%    - Shadow/Highlight Clipping (Stage 3): Fixed [0.2, 0.8] limits saturate
%      pixels below 0.2 to 0 and above 0.8 to 1, losing detail in extreme
%      zones. Adaptive CLAHE (adapthisteq) avoids global clipping.
%    - Corner Rounding (Stage 2): Unconditional 3x3 median filtering slightly
%      rounds sharp 1-pixel corners; an edge-preserving bilateral filter
%      (imbilatfilt) better preserves fine geometric textures.
% -------------------------------------------------------------------------

